/* ---------------------------------------------------------------- email */
function send_mail(string $to, string $subject, string $text): bool {
    $from = setting('support_email');
    $headers = 'From: ' . setting('site_name') . ' <' . $from . ">\r\nReply-To: " . $from . "\r\nContent-Type: text/plain; charset=UTF-8\r\n";
    return @mail($to, '=?UTF-8?B?' . base64_encode($subject) . '?=', $text, $headers, '-f' . $from);
}

/* ---------------------------------------------------------------- markdown-lite for admin-written content */
function sanitize_html(string $html): string {
    // allow a safe subset of tags written in the admin editor
    $html = preg_replace('#<(script|style|iframe|object|embed)[^>]*>.*?</\1>#is', '', $html);
    $html = preg_replace('/\son\w+\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+)/i', '', $html);
    $html = preg_replace('/(href|src)\s*=\s*([\'"])\s*javascript:[^\'"]*\2/i', '$1="#"', $html);
    return strip_tags($html, '<p><br><h2><h3><h4><strong><b><em><i><u><a><ul><ol><li><blockquote><img><table><thead><tbody><tr><th><td><figure><figcaption><hr><span><div>');
}


/* ================================================================ product descriptions */

// Kiratora product copy: original descriptions (US English) written from each product's own data,
// plus the Google description for product pages. Used on first install, for new Card Bot imports and from Admin â€º Tools.

function d_pick(array $p, array $options, int $salt = 0) {
    return $options[(crc32('km' . ($p['handle'] ?? '') . $salt) % count($options))];
}
function d_an(string $word): string { return preg_match('/^[aeiou]/i', $word) && !preg_match('/^(uni|one|eu|use)/i', $word) ? 'an' : 'a'; }
function d_list(array $items): string {
    $items = array_values($items);
    if (count($items) < 2) return (string)($items[0] ?? '');
    return implode(', ', array_slice($items, 0, -1)) . ' and ' . end($items);
}
function d_lang(array $p): string {
    return ['Japanese' => 'Japanese', 'Chinese' => 'Simplified Chinese', 'English' => 'English'][$p['language'] ?? 'English'] ?? (string)$p['language'];
}
const PUBLISHERS = ['PokÃ©mon' => 'The PokÃ©mon Company', 'Riftbound' => 'Riot Games', 'Lorcana' => 'Ravensburger', 'One Piece' => 'Bandai', 'Magic: The Gathering' => 'Wizards of the Coast',
    'Dragon Ball' => 'Bandai', 'Gundam' => 'Bandai', 'Digimon' => 'Bandai', 'Yu-Gi-Oh!' => 'Konami', 'Star Wars' => 'Fantasy Flight Games', 'Weiss Schwarz' => 'Bushiroad'];
const GAME_FULL = ['PokÃ©mon' => 'PokÃ©mon TCG', 'Riftbound' => 'Riftbound: League of Legends TCG', 'Lorcana' => 'Disney Lorcana', 'One Piece' => 'One Piece Card Game',
    'Magic: The Gathering' => 'Magic: The Gathering', 'Dragon Ball' => 'Dragon Ball Super Card Game', 'Gundam' => 'Gundam Card Game', 'Digimon' => 'Digimon Card Game',
    'Yu-Gi-Oh!' => 'Yu-Gi-Oh! TCG', 'Star Wars' => 'Star Wars: Unlimited', 'Weiss Schwarz' => 'Weiss Schwarz', 'Naruto' => 'Naruto Kayou card range',
    'K-Pop Demon Hunters' => 'K-Pop Demon Hunters card range', 'Marvel Rivals' => 'Marvel Rivals card range', 'Sports' => 'sports card range'];

// One or two sentences on what a PokÃ©mon rarity is, in Kiratora's voice.
