    $lad = $c['price_usd'] !== null ? ladder($c) : null;
    $ring[] = ['img' => product_image($c), 'name' => $n, 'price' => $lad ? money($lad['tiers'][0][1]) : '', 'url' => '/products/' . $c['handle']];
    if (count($ring) === 7) break;
}
if (count($ring) < 5) foreach ($singles as $c) { $n = d_clean_name($c); if (isset($seen[$n])) continue; $seen[$n] = 1; $lad = ladder($c);
    $ring[] = ['img' => product_image($c), 'name' => $n, 'price' => money($lad['tiers'][0][1]), 'url' => '/products/' . $c['handle']]; if (count($ring) === 7) break; }
$setName = $show['set']['title'] ?? ''; $clean = preg_replace('/\s*\(.*\)$/', '', $setName);
// the chase-card galaxy: in-stock singles with a photo, one per name
$galaxy = []; $gseen = [];
foreach ($singles as $c) { $n = d_clean_name($c); if (isset($gseen[$n])) continue; $gseen[$n] = 1; $lad = ladder($c);
    $galaxy[] = ['img' => product_image($c), 'name' => $n, 'price' => money($lad['tiers'][0][1]), 'url' => '/products/' . $c['handle'], 'set' => $c['set_name'], 'p' => $c]; if (count($galaxy) === 16) break; }
// photos that drift past in the sky: sealed boxes, category photos and more singles
$float = []; $fseen = [];
foreach ($featured as $c) { $u = product_image($c); if (isset($fseen[$u])) continue; $fseen[$u] = 1; $float[] = ['img' => $u, 'kind' => 'box']; }
foreach ($cats as $c) if (!empty($c['img']) && !isset($fseen[$c['img']])) { $fseen[$c['img']] = 1; $float[] = ['img' => $c['img'], 'kind' => 'box']; }
foreach ($singles as $c) { $u = product_image($c); if (isset($fseen[$u])) continue; $fseen[$u] = 1; $float[] = ['img' => $u, 'kind' => 'card']; }
usort($float, fn($a, $b) => crc32($a['img']) <=> crc32($b['img']));
// the featured product shown as a real 3D box (built from its photo) when the 30th Celebration ETB photo is the homepage photo
$box = null;
if (setting('hero_image') === '/assets/img/30th-celebration-etb.jpg' && ($bp = one("SELECT * FROM products WHERE handle = '30th-celebration-elite-trainer-box' AND published = 1"))) {
