.pill{background:var(--shu);color:#fff;border-radius:10px;padding:0 7px;font-size:12px;line-height:20px}
.side-foot{display:flex;flex-direction:column;gap:6px;padding:12px;border-top:1px solid var(--line);font-size:14px}
