    return <<<'__PKR_HTACCESS__'
# Kiratora â€” Apache config (cPanel / most shared hosts)
Options -Indexes
DirectoryIndex index.php

<IfModule mod_rewrite.c>
  RewriteEngine On
  # never serve app code or the database
  RewriteRule ^(app|data)(/|$) - [F,L]
  # everything that is not a real file goes to index.php
  RewriteCond %{REQUEST_FILENAME} !-f
  RewriteRule ^ index.php [QSA,L]
</IfModule>

<IfModule mod_headers.c>
  Header always set X-Content-Type-Options "nosniff"
  Header always set Referrer-Policy "strict-origin-when-cross-origin"
  Header always set X-Frame-Options "SAMEORIGIN"
  <FilesMatch "\.(css|js|svg|jpg|jpeg|png|webp|woff2)$">
    Header set Cache-Control "public, max-age=2592000"
  </FilesMatch>
</IfModule>
<IfModule mod_deflate.c>
  AddOutputFilterByType DEFLATE text/html text/css application/javascript application/json image/svg+xml application/xml text/plain
</IfModule>
__PKR_HTACCESS__;
}

/* ================================================================ works on any host
   - the stylesheet, scripts and pictures are written out as real files in /assets, so every kind of server
     (Apache, LiteSpeed, Nginx, Plesk, Cloudflare) can send them, even where URL rewriting is off;
   - the shop can live in a sub-folder (example.com/kiratora/);
   - without URL rewriting, links become index.php?r=/shop until a clean address is seen to work. */
function sync_assets(): bool {
    $dir = ROOT . '/assets'; $mark = $dir . '/.build';
    if (@file_get_contents($mark) === BUILD_ID) return true;
    // /admin opens even on servers without URL rewriting
    if (!is_dir(ROOT . '/admin')) @mkdir(ROOT . '/admin', 0755);
    @file_put_contents(ROOT . '/admin/index.php', "<?php\n// Opens the Kiratora admin on servers without URL rewriting. Safe to leave here.\ndefine('KM_STUB_BASE', str_replace('\\\\', '/', dirname(dirname(\$_SERVER['SCRIPT_NAME'] ?? '/admin/index.php'))));\nrequire dirname(__DIR__) . '/index.php';\n");
    foreach (asset_files() as $f => $a) {
        $body = !empty($a[2]) ? base64_decode(str_replace("\n", '', $a[1])) : $a[1];
        $dest = "$dir/$f";
        if (!is_dir(dirname($dest)) && !@mkdir(dirname($dest), 0755, true)) return false;
        $tmp = $dest . '.' . bin2hex(random_bytes(4)) . '.tmp';
        if (@file_put_contents($tmp, $body) === false) return false;
        if (!@rename($tmp, $dest)) { @unlink($tmp); return false; }
    }
    return @file_put_contents($mark, BUILD_ID) !== false;
}
function km_url(string $u): string {
    if ($u === '' || $u[0] !== '/' || str_starts_with($u, '//') || !defined('KM_PRETTY')) return $u;
    if (str_starts_with($u, '/index.php?') || (BASE !== '' && ($u === BASE || str_starts_with($u, BASE . '/')))) return $u;   // already done
    if (preg_match('#^/assets/((?:css|js|img)/[a-z0-9.-]+)#', $u, $m)) return KM_ASSETS_OK ? BASE . $u : BASE . '/index.php?asset=' . $m[1] . '&v=' . substr(BUILD_ID, 0, 8);
    if (KM_PRETTY || str_starts_with($u, '/uploads/')) return BASE . $u;
    if ($u === '/') return BASE . '/';
    $frag = ''; if (($h = strpos($u, '#')) !== false) { $frag = substr($u, $h); $u = substr($u, 0, $h); }
    $q = ''; if (($i = strpos($u, '?')) !== false) { $q = '&' . substr($u, $i + 1); $u = substr($u, 0, $i); }
    return BASE . '/index.php?r=' . $u . $q . $frag;
}
// rewrites the site's own addresses in a finished page (only used in a sub-folder, without URL rewriting, or when /assets could not be written)
function km_out(string $buf): string {
    foreach (headers_list() as $hd) if (stripos($hd, 'content-type:') === 0 && stripos($hd, 'text/html') === false) return $buf;   // only pages
    $buf = preg_replace_callback('#(?<=["\'(]|, )/(?!/)[^"\'\s)<>,]+#', fn($m) => km_url(html_entity_decode($m[0], ENT_QUOTES)), $buf);
    if (BASE !== '') $buf = str_replace(['href="/"', "href='/'"], ['href="' . BASE . '/"', "href='" . BASE . "/'"], $buf);
    if (!KM_PRETTY) {
        $here = BASE . '/index.php?r=' . KM_PATH;
        // relative "?tab=..." links keep the current page
        $buf = str_replace('href="?', 'href="' . $here . '&amp;', $buf);
        // GET forms: the browser drops the query string of the action, so the page goes in a hidden field
        $buf = preg_replace_callback('#<form\b([^>]*)>#i', function ($m) {
            $at = $m[1];
            if (preg_match('#\bmethod\s*=\s*["\']?post#i', $at) || preg_match('#\bdata-(add|set|quick-paste)\b#i', $at)) return $m[0];
            $r = KM_PATH;
            if (preg_match('#\baction\s*=\s*"([^"]*)"#i', $at, $a)) {
                if (preg_match('#index\.php\?r=([^&"]*)#', html_entity_decode($a[1]), $rr)) $r = $rr[1];
                elseif ($a[1] !== '' && !str_contains($a[1], 'index.php')) return $m[0];
                $at = str_replace($a[0], 'action="' . BASE . '/index.php"', $at);
            } else $at .= ' action="' . BASE . '/index.php"';
            return '<form' . $at . '><input type="hidden" name="r" value="' . htmlspecialchars($r) . '">';
        }, $buf);
    }
    return $buf;
}
function install(): void {
    if (is_file(DATA . '/config.php')) return;
    @set_time_limit(120);
    foreach ([DATA, ROOT . '/uploads', ROOT . '/uploads/products', ROOT . '/uploads/pages'] as $d) if (!is_dir($d) && !@mkdir($d, 0775, true)) install_fail("Could not create the folder $d. Make the website folder writable and refresh.");
    file_put_contents(DATA . '/.htaccess', "Require all denied\nDeny from all\n");
    file_put_contents(DATA . '/index.html', '');
    file_put_contents(ROOT . '/uploads/.htaccess', "<FilesMatch \"\\.(php|phtml|phar)$\">\n  Require all denied\n</FilesMatch>\n");
    $name = 'kiratora-' . bin2hex(random_bytes(8)) . '.sqlite';
    $packed = file_get_contents(__FILE__, false, null, __COMPILER_HALT_OFFSET__);
    $raw = $packed !== false && strlen(trim($packed)) > 0 ? gzdecode(ltrim($packed, "\r\n")) : false;
    if ($raw === false || $raw === '') install_fail('The product data at the end of index.php is missing or damaged. Upload index.php again in binary mode.');
    if (file_put_contents(DATA . "/$name", $raw) === false) install_fail('Could not write the database into the data folder.');
    file_put_contents(DATA . '/config.php', "<?php return ['db' => " . var_export($name, true) . "];\n");
    $ht = ROOT . '/.htaccess';
    if (!is_file($ht)) @file_put_contents($ht, htaccess_rules() . "\n");
    elseif (!str_contains((string)file_get_contents($ht), 'Kiratora')) {
        $old = (string)file_get_contents($ht);
        @copy($ht, $ht . '.old-backup');
        preg_match_all('/^.*(AddHandler|SetHandler|AddType application\/x-httpd|php_value|php_flag|suPHP).*$/mi', $old, $m);
        @file_put_contents($ht, htaccess_rules() . "\n" . ($m[0] ? "\n# Kept from your previous .htaccess (PHP version settings)\n" . implode("\n", $m[0]) . "\n" : ''));
    }
}
function install_fail(string $msg): never {
    http_response_code(500);
    echo '<!doctype html><meta charset="utf-8"><title>Kiratora setup</title><body style="font:16px system-ui;padding:40px;max-width:640px"><h1>Setup needs one fix</h1><p>' . h($msg) . '</p></body>';
    exit;
}
function serve_asset(string $file): never {
    $a = asset_files()[$file] ?? null;
    if (!$a) { http_response_code(404); exit; }
    $body = !empty($a[2]) ? base64_decode(str_replace("
", '', $a[1])) : $a[1];
    $etag = '"' . md5($a[1]) . '"';
    header('Content-Type: ' . $a[0] . (!empty($a[2]) ? '' : '; charset=utf-8'));
    header('Cache-Control: public, max-age=2592000');
    header('ETag: ' . $etag);
    header('Vary: Accept-Encoding');
    if (($_SERVER['HTTP_IF_NONE_MATCH'] ?? '') === $etag) { http_response_code(304); exit; }
    if (empty($a[2]) && strlen($body) > 2048 && function_exists('gzencode') && str_contains((string)($_SERVER['HTTP_ACCEPT_ENCODING'] ?? ''), 'gzip') && !ini_get('zlib.output_compression')) {
        header('Content-Encoding: gzip'); $body = gzencode($body, 6);
    }
    header('Content-Length: ' . strlen($body));
    echo $body;
    exit;
}

/* ================================================================ front door */
// the folder the shop lives in ('' at the domain root): from the script address, or from where this file sits under the web root
$__sn = str_replace('\\', '/', (string)($_SERVER['SCRIPT_NAME'] ?? ''));
if (defined('KM_STUB_BASE')) $__b = KM_STUB_BASE;
elseif (basename($__sn) === basename(__FILE__) && realpath((string)($_SERVER['SCRIPT_FILENAME'] ?? '')) === realpath(__FILE__)) $__b = dirname($__sn);
else { $__dr = realpath((string)($_SERVER['DOCUMENT_ROOT'] ?? '')); $__here = str_replace('\\', '/', __DIR__); $__b = $__dr && str_starts_with($__here, str_replace('\\', '/', $__dr)) ? substr($__here, strlen(str_replace('\\', '/', $__dr))) : ''; }
$__b = str_replace('\\', '/', (string)$__b);
define('BASE', ($__b === '/' || $__b === '.' || $__b === '') ? '' : rtrim($__b, '/'));
$path = rawurldecode(parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH) ?: '/');
if (BASE !== '' && str_starts_with($path, BASE . '/')) $path = substr($path, strlen(BASE));
elseif (BASE !== '' && $path === BASE) $path = '/';
$path = '/' . trim($path, '/');
$viaQuery = false;
if (str_starts_with($path, '/index.php/')) $path = substr($path, 10);                       // index.php/shop style
if (($path === '/index.php' || $path === '/') && isset($_GET['r']) && is_string($_GET['r'])) { $path = '/' . trim($_GET['r'], '/'); $viaQuery = true; }
if (isset($_GET['asset']) && is_string($_GET['asset']) && preg_match('#^(?:css|js|img)/[a-z0-9.-]+$#', $_GET['asset'])) serve_asset($_GET['asset']);
if (PHP_SAPI === 'cli-server' && str_starts_with($path, '/uploads/') && is_file(ROOT . $path) && !str_ends_with($path, '.php')) return false;
if (preg_match('#^/assets/((?:css|js|img)/[a-z0-9.-]+)$#', $path, $m)) serve_asset($m[1]);
install();
define('KM_ASSETS_OK', sync_assets());
// clean addresses work as soon as one reaches the shop without index.php?r= (the first visitor's browser checks this once)
if (!$viaQuery && !defined('KM_STUB_BASE') && $path !== '/' && $path !== '/index.php' && !str_starts_with((string)parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH), BASE . '/index.php') && setting('pretty_urls') !== '1') set_setting('pretty_urls', '1');
define('KM_PRETTY', PHP_SAPI === 'cli-server' && !getenv('KM_NO_REWRITE') ? true : setting('pretty_urls') === '1');
define('KM_PATH', $path);
if ($path === '/kiratora-url-check') { header('Content-Type: text/plain'); header('Cache-Control: no-store'); echo 'ok'; exit; }
// compress pages (not admin downloads or images) when the server is not already doing it
if (!str_starts_with($path, '/admin') && !str_starts_with($path, '/img/') && extension_loaded('zlib') && !ini_get('zlib.output_compression') && !headers_sent()) ob_start('ob_gzhandler');
if (BASE !== '' || !KM_PRETTY || !KM_ASSETS_OK) ob_start('km_out');
if ($path === '/index.php' && empty($_GET['p'])) redirect('/', 301);
if (!$viaQuery && $path !== '/' && str_ends_with((string)parse_url($_SERVER['REQUEST_URI'] ?? '', PHP_URL_PATH), '/') && !str_starts_with($path, '/admin')) {
    redirect($path . (($_SERVER['QUERY_STRING'] ?? '') !== '' ? '?' . $_SERVER['QUERY_STRING'] : ''), 301);
}
// one address for Google: https://kiratora.com (no www, no http) once the site runs on its own domain
$canon = parse_url(setting('site_url'));
$host = strtolower($_SERVER['HTTP_HOST'] ?? '');
$https = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || ($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https';
if (BASE === '' && !empty($canon['host']) && ($host === 'www.' . $canon['host'] || ($host === $canon['host'] && !$https && ($canon['scheme'] ?? '') === 'https' && PHP_SAPI !== 'cli-server'))) {
    header('Location: ' . $canon['scheme'] . '://' . $canon['host'] . ($_SERVER['REQUEST_URI'] ?? '/'), true, 301); exit;
}
if (str_starts_with($path, '/admin')) { admin_main($path); exit; }
store_route($path);

